using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using NUnit.Framework;
using UnityEngine;
using SporeGobbo.Geometry;
using SporeGobbo.CampCandidate.Preview;
using SporeGobbo.Input;
namespace SporeGobbo.CampCandidate.Tests
{
 public sealed class Stage58Tests
 {
  static CampSession New()=>new CampSession(Stage57Layout.Create());
  // Frozen pre-optimization BFS serves as a behavioral oracle, not another live terrain authority.
  static List<Point2> Legacy(CampSession s,Point2 from,Point2 to,int size){var result=new List<Point2>();int w=192,start=(int)Math.Floor(from.Y)*w+(int)Math.Floor(from.X),goal=(int)Math.Floor(to.Y)*w+(int)Math.Floor(to.X);if(!s.Fits(from,size)||!s.Fits(to,size))return result;var previous=new Dictionary<int,int>{{start,-1}};var q=new Queue<int>();q.Enqueue(start);while(q.Count>0){int i=q.Dequeue();if(i==goal)break;int x=i%w,y=i/w;foreach(int n in new[]{i-1,i+1,i-w,i+w}){int nx=n%w,ny=n/w;if(nx<0||ny<0||nx>=w||ny>=w||Math.Abs(nx-x)+Math.Abs(ny-y)!=1||previous.ContainsKey(n)||!s.Fits(new Point2(nx+.5,ny+.5),size))continue;previous[n]=i;q.Enqueue(n);}}if(!previous.ContainsKey(goal))return result;for(int i=goal;i!=-1;i=previous[i])result.Add(new Point2(i%w+.5,i/w+.5));result.Reverse();return result;}
  [Test]public void NavigationMatchesFrozenPathsBeforeAndAfterConstructionAndEdits(){var s=New();var f=s.Definition.Marker("fire").Interaction;void Check(){foreach(int size in new[]{1,3,5})foreach(var m in s.Definition.Markers)Assert.That(s.Route(f,m.Interaction,size),Is.EqualTo(Legacy(s,f,m.Interaction,size)),m.Id+" / "+size);foreach(var room in s.Definition.Bedrooms)Assert.That(s.Route(f,room.Entrance,3),Is.EqualTo(Legacy(s,f,room.Entrance,3)));}Check();s.FakeReturn(3,5,2);for(int i=0;i<3;i++)s.ConstructNext(out _);Check();var cells=new List<DualTile>();for(int y=100;y<130;y++)for(int x=70;x<90;x++)if(s.Definition.Category(x,y)==CampCell.Expansion)cells.Add(new DualTile(x,y));s.DigPlayer(cells);Check();}
  [Test]public void NavigationWorkspaceWrapAndReturnedPathsStayIndependent(){var s=New();var f=s.Definition.Marker("fire").Interaction;var goal=s.Definition.Marker("run.departure").Interaction;var path=s.Route(f,goal,3);var copy=path.ToArray();typeof(CampSession).GetField("routeGeneration",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(s,int.MaxValue);Assert.That(s.Route(f,goal,3),Is.EqualTo(copy));s.Route(goal,f,1);Assert.That(path,Is.EqualTo(copy));foreach(string field in new[]{"routePrevious","routeSeen","routeQueue"})Assert.That(((int[])typeof(CampSession).GetField(field,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(s)).Length,Is.EqualTo(192*192));}
  [Test]public void ImmutableDefinitionReuseNeverSharesMutableOccupancy(){var definition=Stage57Layout.Create();var a=new CampSession(definition);var b=new CampSession(definition);a.FakeReturn(1,5,2);a.ConstructNext(out _);Assert.That(b.Revision+b.Established+b.Living,Is.Zero);Assert.That(b.Definition.Fingerprint(),Is.EqualTo(definition.Fingerprint()));Assert.That(b.Terrain.IsSolid(100,86));Assert.That(a.Terrain.IsSolid(100,86),Is.False);}
  [Test]public void FrozenLayoutAndMarkerIdentitiesArePreserved(){Assert.That(Stage57Layout.Create().Fingerprint(),Is.EqualTo("5414BE3EC0CAA17B"));Assert.That(Stage57Layout.Create().Markers.Select(m=>m.Id),Is.EqualTo(Stage57Layout.Create(1).Markers.Select(m=>m.Id)));}
  [Test]public void PausedClockDoesNotStartPlanningSpawnOrExcavation(){var s=New();var clock=new CampConstructionPreview(s){BuildDorm=true,FinishCurrent=true};for(int i=0;i<10;i++)clock.Tick(0);Assert.That(s.Construction,Is.Null);Assert.That(s.Living+s.Established+s.Revision,Is.Zero);clock.Tick(1.0/60);Assert.That(s.Construction,Is.Not.Null);var p=s.Residents[0].Position;int rev=s.Revision;for(int i=0;i<10;i++)clock.Tick(0);Assert.That(s.Residents[0].Position,Is.EqualTo(p));Assert.That(s.Revision,Is.EqualTo(rev));}
  [Test]public void ModalAndPauseContextsRejectDirectDigAndInteraction(){var go=new GameObject("isolated input test");try{var preview=go.AddComponent<Stage57Preview>();foreach(var context in new[]{SporeInputContext.Modal,SporeInputContext.Story,SporeInputContext.Pause,SporeInputContext.Wheel}){preview.PreviewInputContext=context;Assert.That(preview.WorldInputAllowed,Is.False);Assert.That(preview.Dig(new Point2(0,0)),Is.Zero);Assert.That(preview.Interact(),Does.Contain("blocked"));}preview.PreviewInputContext=SporeInputContext.Gameplay;preview.PauseSimulation=true;Assert.That(preview.Dig(new Point2(0,0)),Is.Zero);}finally{UnityEngine.Object.DestroyImmediate(go);}}
  [Test]public void SemanticTextureTracksDefinitionWhenSwitchingShopOptions(){var go=new GameObject("isolated surface test");try{var p=go.AddComponent<Stage57Preview>();var texture=new Texture2D(192,192,TextureFormat.RGBA32,false,true);typeof(Stage57Preview).GetField("surface",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(p,texture);foreach(int option in new[]{0,1,0}){var definition=Stage57Layout.Create(option);typeof(Stage57Preview).GetProperty("Session").SetValue(p,new CampSession(definition));typeof(Stage57Preview).GetMethod("RefreshSurface",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(p,null);var pixels=texture.GetPixels();for(int y=0;y<192;y++)for(int x=0;x<192;x++)Assert.That(pixels[y*192+x].r>.9f,Is.EqualTo(definition.Protected(x,y)));}}finally{UnityEngine.Object.DestroyImmediate(go);}}
  [Test]public void ResidentViewIsReadOnlyLiveAndDoesNotAllocateANewWrapperPerRead(){var s=New();var view=s.Residents;s.AddBuddy();Assert.That(view.Count,Is.EqualTo(1));Assert.That(ReferenceEquals(view,s.Residents));Assert.Throws<NotSupportedException>(()=>((IList<PreviewResident>)view).Add(new PreviewResident("bad",new Point2(0,0))));}
  [Serializable]sealed class Log{public int[] commands;}
  static CampSession Replay(Log log){var s=New();foreach(int command in log.commands)switch(command){case 0:s.FakeReturn(3,5,2);break;case 1:if(!s.ConstructNext(out string why))throw new Exception(why);break;case 2:s.BuddyDied();break;case 3:s.FakeReturn(1,2,1);break;}return s;}
  [Test]public void IsolatedIntentLogReloadPreservesBedOwnershipAndFakeReturns(){var log=new Log{commands=new[]{0,1,1,2,3,1}};var a=Replay(log);var b=Replay(JsonUtility.FromJson<Log>(JsonUtility.ToJson(log)));Assert.That(b.Residents.Select(x=>x.Id+":"+x.Slot+":"+x.Alive),Is.EqualTo(a.Residents.Select(x=>x.Id+":"+x.Slot+":"+x.Alive)));Assert.That(b.Mushrooms,Is.EqualTo(a.Mushrooms));Assert.That(b.Returns,Is.EqualTo(a.Returns));for(int y=0;y<192;y++)for(int x=0;x<192;x++)Assert.That(b.Terrain.IsSolid(x,y),Is.EqualTo(a.Terrain.IsSolid(x,y)));}
  sealed class MockTransition{public readonly CampSession Source;public CampSession Active;int revision;bool pending,committed;string arrival;public MockTransition(CampSession source){Source=Active=source;}public void Prepare(){revision=Source.Revision;pending=true;}public void Cancel(){pending=false;}public bool Commit(CampSession destination){if(!pending||committed||revision!=Source.Revision||!destination.Fits(destination.Definition.Marker("run.departure").Interaction,3))return false;Active=destination;arrival="run.departure";pending=false;committed=true;return true;}public string ConsumeArrival(){var s=arrival;arrival=null;return s;}}
  [Test]public void MockTransitionCancellationRevisionAndOneShotArrivalAreIsolated(){var source=New();var destination=New();var cancelled=new MockTransition(source);cancelled.Prepare();cancelled.Cancel();Assert.That(cancelled.Commit(destination),Is.False);Assert.That(cancelled.Active,Is.SameAs(source));var stale=new MockTransition(source);stale.Prepare();var dirt=Enumerable.Range(0,192*192).First(i=>source.Definition.Category(i%192,i/192)==CampCell.Expansion && source.Terrain.IsSolid(i%192,i/192));Assert.That(source.DigPlayer(new[]{new DualTile(dirt%192,dirt/192)}),Is.EqualTo(1));Assert.That(stale.Commit(destination),Is.False);var ticket=new MockTransition(source);ticket.Prepare();Assert.That(ticket.Commit(destination));Assert.That(ticket.Commit(destination),Is.False);Assert.That(ticket.ConsumeArrival(),Is.EqualTo("run.departure"));Assert.That(ticket.ConsumeArrival(),Is.Null);Assert.That(source.Established+source.Living,Is.Zero);}
 }
}
